package config

import (
	"fmt"
	"os"
	"path/filepath"

	"github.com/BurntSushi/toml"
)

// Config holds all wt configuration. Every field has a sensible default.
// Resolved via: defaults → global (~/.config/wt/config.toml) → global per-repo → .wt.toml
type Config struct {
	// BaseBranch is the branch worktrees are created from and rebased onto.
	// Common values: "main", "staging", "develop"
	BaseBranch string `toml:"base_branch"`

	// Remote is the git remote name. Almost always "origin".
	Remote string `toml:"remote"`

	// BranchPrefix is prepended to new branch names: "<prefix>/<name>".
	// Default: git user's first name (lowercase). Set to "" to disable prefixing.
	// Pointer so we can distinguish "not set" (nil) from "explicitly empty" ("").
	BranchPrefix *string `toml:"branch_prefix"`

	// WorktreePrefix controls the directory naming: "<prefix><name>".
	// Default: "wt-<repo>-". Set to customize (e.g., "wt-" for shorter names).
	// Pointer so we can distinguish "not set" (nil) from "explicitly empty" ("").
	WorktreePrefix *string `toml:"worktree_prefix"`

	// StaleThreshold is the number of days after which a worktree with no open PR
	// is considered stale in `wt list`. Default: 7.
	StaleThreshold int `toml:"stale_threshold"`

	// AutoInstall controls whether `wt rebase` runs the package manager
	// install command when the lockfile changes. Default: true.
	// Pointer to distinguish "not set" (nil → true) from "explicitly false".
	AutoInstall *bool `toml:"auto_install"`

	// Init configures the `wt init` command behavior.
	Init InitConfig `toml:"init"`
}

// globalFile is the on-disk shape of ~/.config/wt/config.toml.
// Top-level fields are defaults; [repos.<name>] sections override per repo.
type globalFile struct {
	Config
	Repos map[string]Config `toml:"repos"`
}

// InitConfig controls what `wt init` does. Entirely config-driven —
// no auto-detection. Configure in .wt.toml under [init].
type InitConfig struct {
	// CopyFiles are copied from the main worktree if missing in the target.
	CopyFiles []string `toml:"copy_files"`

	// Commands are shell commands run sequentially during init.
	Commands []string `toml:"commands"`
}

// Load reads config with layered precedence:
//  1. Hardcoded defaults (base_branch="main", remote="origin")
//  2. Global defaults (~/.config/wt/config.toml top-level fields)
//  3. Global per-repo ([repos.<repoName>] section)
//  4. Repo-local (.wt.toml in the main worktree root)
//
// Each layer only overrides fields it explicitly sets.
func Load(dir, repoName string) (*Config, error) {
	cfg := &Config{
		BaseBranch: "main",
		Remote:     "origin",
	}

	// Layer 1+2: global defaults + per-repo overrides
	if globalPath, err := globalConfigPath(); err == nil {
		data, readErr := os.ReadFile(globalPath)
		if readErr == nil {
			var gf globalFile
			if err := toml.Unmarshal(data, &gf); err != nil {
				return nil, fmt.Errorf("global config (%s): %w", globalPath, err)
			}
			// Apply global defaults
			mergeConfig(cfg, &gf.Config)
			// Apply per-repo overrides
			if repoName != "" {
				if repoCfg, ok := gf.Repos[repoName]; ok {
					mergeConfig(cfg, &repoCfg)
				}
			}
		} else if !os.IsNotExist(readErr) {
			return nil, fmt.Errorf("global config (%s): %w", globalPath, readErr)
		}
	}

	// Layer 3: repo-local .wt.toml (overrides non-zero fields, same as other layers)
	repoPath := filepath.Join(dir, ".wt.toml")
	if data, err := os.ReadFile(repoPath); err == nil {
		var repoCfg Config
		if err := toml.Unmarshal(data, &repoCfg); err != nil {
			return nil, fmt.Errorf("repo config (%s): %w", repoPath, err)
		}
		mergeConfig(cfg, &repoCfg)
	}

	return cfg, nil
}

// mergeConfig copies non-zero fields from src into dst.
func mergeConfig(dst, src *Config) {
	if src.BaseBranch != "" {
		dst.BaseBranch = src.BaseBranch
	}
	if src.Remote != "" {
		dst.Remote = src.Remote
	}
	if src.BranchPrefix != nil {
		dst.BranchPrefix = src.BranchPrefix
	}
	if src.WorktreePrefix != nil {
		dst.WorktreePrefix = src.WorktreePrefix
	}
	if src.StaleThreshold > 0 {
		dst.StaleThreshold = src.StaleThreshold
	}
	if src.AutoInstall != nil {
		dst.AutoInstall = src.AutoInstall
	}
	if len(src.Init.CopyFiles) > 0 {
		dst.Init.CopyFiles = src.Init.CopyFiles
	}
	if len(src.Init.Commands) > 0 {
		dst.Init.Commands = src.Init.Commands
	}
}

// globalConfigPath returns ~/.config/wt/config.toml.
func globalConfigPath() (string, error) {
	home, err := os.UserHomeDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(home, ".config", "wt", "config.toml"), nil
}

// EffectiveBranchName builds the full branch name for a new worktree.
// If BranchPrefix is explicitly set (even to ""), uses that value.
// Otherwise falls back to gitUsername. Returns just "name" if both are empty.
func (c *Config) EffectiveBranchName(name, gitUsername string) string {
	var prefix string
	if c.BranchPrefix != nil {
		prefix = *c.BranchPrefix
	} else {
		prefix = gitUsername
	}
	if prefix == "" {
		return name
	}
	return prefix + "/" + name
}

// EffectiveStaleThreshold returns the stale threshold in days, defaulting to 7.
func (c *Config) EffectiveStaleThreshold() int {
	if c.StaleThreshold > 0 {
		return c.StaleThreshold
	}
	return 7
}

// EffectiveAutoInstall returns whether auto-install is enabled (default: true).
func (c *Config) EffectiveAutoInstall() bool {
	if c.AutoInstall != nil {
		return *c.AutoInstall
	}
	return true
}

// EffectiveWorktreeDir builds the worktree directory name.
// Default pattern: "wt-<repo>/<name>" (nested under a per-project folder).
// If WorktreePrefix is explicitly set (even to ""), uses flat layout instead.
func (c *Config) EffectiveWorktreeDir(repoName, name string) string {
	if c.WorktreePrefix != nil {
		return *c.WorktreePrefix + name
	}
	return filepath.Join("wt-"+repoName, name)
}
package cmd

import (
	"fmt"
	"io/fs"
	"os"
	"os/exec"
	"path/filepath"
	"strings"

	"github.com/mvwi/wt/internal/ui"
	"github.com/spf13/cobra"
)

var initCmd = &cobra.Command{
	Use:     "init",
	GroupID: groupWorkflow,
	Short:   "Initialize worktree (copy files, run commands)",
	Long: `Initialize a worktree for development.

When [init] is configured in .wt.toml, runs exactly those steps:

  copy_files — files copied from the main worktree (if missing)
  commands   — shell commands run sequentially

When no [init] section exists, auto-detects common patterns:

  • Copies .env files found in the main worktree
  • Copies AI config (.claude, .cursorrules, .cursor/rules)
  • Detects package manager from lockfile and runs install
  • Detects Prisma schema and runs prisma generate

Example config (overrides auto-detection):

  [init]
  copy_files = [".env", ".env.local"]
  commands = ["pnpm install", "npx prisma generate"]`,
	Example: `  wt init                 Initialize current worktree
  wt new feature --init   Create worktree + initialize in one step`,
	RunE: runInit,
}

func init() {
	rootCmd.AddCommand(initCmd)
}

func runInit(cmd *cobra.Command, args []string) error {
	ctx, err := newContext()
	if err != nil {
		return err
	}

	cwd, err := os.Getwd()
	if err != nil {
		return fmt.Errorf("cannot determine current directory: %w", err)
	}
	return runInitIn(cwd, ctx)
}

// initStep records the outcome of a single initialization step.
type initStep struct {
	label  string // e.g. "copy .env" or "pnpm install"
	status string // "ok", "skip", "fail"
	detail string // reason for skip/fail, empty on success
}

func runInitIn(dir string, ctx *cmdContext) error {
	// Check if we're in the main repo
	if dir == ctx.MainWorktree || isSubpath(dir, ctx.MainWorktree) {
		return fmt.Errorf("you're in the main repo\n   Switch to a worktree first: wt switch <name>")
	}

	copyFiles := ctx.Config.Init.CopyFiles
	commands := ctx.Config.Init.Commands
	configured := len(copyFiles) > 0 || len(commands) > 0

	// Auto-detect when no [init] section is configured
	if !configured {
		copyFiles, commands = detectInit(ctx.MainWorktree)
		if len(copyFiles) == 0 && len(commands) == 0 {
			fmt.Println("Nothing to initialize — no [init] config and nothing detected.")
			fmt.Println()
			fmt.Println("Add an [init] section to .wt.toml to configure setup:")
			fmt.Println()
			fmt.Println("  [init]")
			fmt.Println("  copy_files = [\".env\"]")
			fmt.Println("  commands = [\"pnpm install\"]")
			return nil
		}
	}

	fmt.Println("Initializing worktree…")
	fmt.Println()

	var steps []initStep

	// Step 1: Copy files/directories from main worktree
	for _, file := range copyFiles {
		src := filepath.Join(ctx.MainWorktree, file)
		dst := filepath.Join(dir, file)

		if !fileExists(src) {
			steps = append(steps, initStep{"copy " + file, "skip", "not found in main worktree"})
			continue
		}
		if fileExists(dst) {
			steps = append(steps, initStep{"copy " + file, "skip", "already exists"})
			continue
		}

		if isDir(src) {
			if err := copyDirRecursive(src, dst); err != nil {
				steps = append(steps, initStep{"copy " + file, "fail", err.Error()})
			} else {
				steps = append(steps, initStep{"copy " + file, "ok", ""})
			}
		} else {
			data, err := os.ReadFile(src)
			if err != nil {
				steps = append(steps, initStep{"copy " + file, "fail", err.Error()})
			} else if err := os.WriteFile(dst, data, 0644); err != nil {
				steps = append(steps, initStep{"copy " + file, "fail", err.Error()})
			} else {
				steps = append(steps, initStep{"copy " + file, "ok", ""})
			}
		}
	}

	// Step 2: Run commands
	for _, command := range commands {
		fmt.Printf("  %s %s\n", ui.Dim("$"), command)
		if err := runShellString(dir, command); err != nil {
			steps = append(steps, initStep{"run " + command, "fail", err.Error()})
		} else {
			steps = append(steps, initStep{"run " + command, "ok", ""})
		}
		fmt.Println()
	}

	// Print summary
	hasFailures := false
	for _, s := range steps {
		switch s.status {
		case "ok":
			fmt.Printf("  %s  %s\n", ui.Green(ui.Pass), s.label)
		case "skip":
			fmt.Printf("  %s  %s %s\n", ui.Dim(ui.Dash), s.label, ui.Dim("("+s.detail+")"))
		case "fail":
			fmt.Printf("  %s  %s %s\n", ui.Red(ui.Fail), s.label, ui.Dim("("+s.detail+")"))
			hasFailures = true
		}
	}

	fmt.Println()
	if hasFailures {
		ui.Warn("Worktree initialized with errors")
	} else {
		ui.Success("Worktree initialized")
	}

	if !configured {
		fmt.Println()
		fmt.Println(ui.Dim("Tip: add [init] to .wt.toml to customize this behavior"))
	}

	return nil
}

// detectInit auto-detects initialization steps from the main worktree.
// Returns env files to copy and install commands to run.
func detectInit(mainWorktree string) (copyFiles []string, commands []string) {
	// Detect .env files
	envFiles := []string{".env", ".env.local", ".env.development", ".env.test"}
	for _, f := range envFiles {
		if fileExists(filepath.Join(mainWorktree, f)) {
			copyFiles = append(copyFiles, f)
		}
	}

	// Detect AI config files/directories
	aiConfigs := []string{".claude", ".cursorrules", ".cursor/rules"}
	for _, f := range aiConfigs {
		if fileExists(filepath.Join(mainWorktree, f)) {
			copyFiles = append(copyFiles, f)
		}
	}

	// Detect package manager from lockfile
	var execRunner string
	for _, lf := range knownLockfiles {
		if fileExists(filepath.Join(mainWorktree, lf.file)) {
			commands = append(commands, lf.command)
			execRunner = lf.exec
			break
		}
	}

	// Detect Prisma schema anywhere in the repo (requires a JS package manager)
	if execRunner != "" {
		if schemaPath := findPrismaSchema(mainWorktree); schemaPath != "" {
			commands = append(commands, execRunner+" prisma generate --schema "+shellQuoteInit(schemaPath))
		}
	}

	return
}

func runShellString(dir, command string) error {
	cmd := exec.Command("sh", "-c", command)
	cmd.Dir = dir
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

// copyDirRecursive copies a directory tree from src to dst, preserving permissions.
func copyDirRecursive(src, dst string) error {
	return filepath.WalkDir(src, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}

		rel, err := filepath.Rel(src, path)
		if err != nil {
			return err
		}
		target := filepath.Join(dst, rel)

		if d.IsDir() {
			info, err := d.Info()
			if err != nil {
				return err
			}
			return os.MkdirAll(target, info.Mode())
		}

		data, err := os.ReadFile(path)
		if err != nil {
			return err
		}
		info, err := d.Info()
		if err != nil {
			return err
		}
		return os.WriteFile(target, data, info.Mode())
	})
}

// shellQuoteInit wraps a string in single quotes for safe shell interpolation.
func shellQuoteInit(s string) string {
	if !strings.ContainsAny(s, " \t\n'\"\\$`|&;<>(){}[]!*?~") {
		return s
	}
	return "'" + strings.ReplaceAll(s, "'", `'\''`) + "'"
}

// findPrismaSchema walks the tree looking for a .prisma file, skipping
// node_modules and other heavy dirs. Returns the repo-relative path to
// the first schema found, or "" if none exists.
func findPrismaSchema(root string) string {
	skipDirs := map[string]bool{
		"node_modules": true,
		".git":         true,
		"dist":         true,
		".next":        true,
		".turbo":       true,
	}
	var result string
	_ = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil {
			return nil // skip unreadable paths
		}
		if result != "" {
			return fs.SkipAll
		}
		if d.IsDir() && skipDirs[d.Name()] {
			return fs.SkipDir
		}
		if !d.IsDir() && filepath.Ext(d.Name()) == ".prisma" {
			rel, err := filepath.Rel(root, path)
			if err != nil {
				return nil
			}
			result = rel
			return fs.SkipAll
		}
		return nil
	})
	return result
}
package cmd

import "path/filepath"

// lockfileMapping maps a lockfile name to its install command.
type lockfileMapping struct {
	file    string
	command string
	exec    string // exec runner for post-install codegen (JS-only)
}

// knownLockfiles is the ordered list of lockfile→install-command mappings.
// Order matters: first match wins (pnpm preferred over npm, etc.).
var knownLockfiles = []lockfileMapping{
	{"pnpm-lock.yaml", "pnpm install --frozen-lockfile", "pnpm exec"},
	{"yarn.lock", "yarn install --frozen-lockfile", "yarn"},
	{"bun.lockb", "bun install --frozen-lockfile", "bunx"},
	{"package-lock.json", "npm ci", "npx"},
	{"go.sum", "go mod download", ""},
	{"Gemfile.lock", "bundle install", ""},
	{"Cargo.lock", "cargo fetch", ""},
	{"requirements.txt", "pip install -r requirements.txt", ""},
	{"pyproject.toml", "pip install -e .", ""},
}

// detectInstallCommand checks a directory for known lockfiles and returns
// the lockfile name and install command. Returns ("", "") if none found.
func detectInstallCommand(dir string) (lockfile, command string) {
	for _, lf := range knownLockfiles {
		if fileExists(filepath.Join(dir, lf.file)) {
			return lf.file, lf.command
		}
	}
	return "", ""
}

