// worktreeForBranch returns the path of the worktree that has branch checked
// out, or "" if none does.
func worktreeForBranch(branch string) string {
	wts, err := git.ListWorktrees()
	if err != nil {
		return ""
	}
	for _, wt := range wts {
		if wt.Branch == branch {
			return wt.Path
		}
	}
	return ""
}

