	fmt.Printf("Lockfile changed (%s) — running install...\n", lockfile)
	fmt.Printf("  %s %s\n", ui.Dim("$"), command)
	if err := runShellString(cwd, command); err != nil {
		fmt.Println()
		ui.Warn("Install failed — run manually: %s", command)
	}
